/// The retry notice for a retryable exec Err, or null when the failure is
/// final. Two retry classes (issue #2415 + gh-1444 C5):
///
/// - a timeout the MODEL passed is a transient-failure candidate (a hung
///   network call under a deliberate bail cap) and is retried; a
///   SHELL-default timeout (no timeout argument) is the harness's own cap
///   firing — re-running a long command up to 3× parks the turn ("looked
///   stuck"), so it fails once with the honest text and the captured
///   partial output;
/// - fd-table exhaustion (EMFILE) gets exactly ONE retry after a settle
///   beat, because drains that are mid-flight when the first spawn hits
///   the limit often finish within it. A second EMFILE is a hard
///   environmental wall — the typed fd-pressure text (operational, no
///   "uncaught exception" mislabel) reports it as-is.
String? _execRetryNotice(
  ExecutionError error, {
  required num? timeoutArg,
  required int attempt,
  required bool canRetry,
}) {
  if (error.code == ExecutionErrorCode.fdExhausted) {
    if (!canRetry || attempt != 1) return null;
    return '[bash attempt $attempt hit fd pressure (too many open files) '
        '— retrying once]';
  }
  if (error.code == ExecutionErrorCode.timeout &&
      canRetry &&
      timeoutArg != null) {
    return '[bash attempt $attempt/${bashToolMaxRetries + 1} timed out'
        ' after ${timeoutArg}s — '
        'retrying]';
  }
  return null;
}

/// The user-visible error for a non-retryable bash exec failure.
StateError _bashFailureError(
  ExecutionError error,
  List<String> notices,
  num? timeoutArg,
) {
  // gh-1053 (review rework): a killed call's error carries the captured

  // gh-1053 (review rework): a killed call's error carries the captured
  // partial output — render it so the model sees WHERE the call stalled,
  // not just the verdict.
  return switch (error.code) {
    ExecutionErrorCode.aborted => StateError(
      _bashFailureWithCapture(error, _appendStatus('', 'Command aborted')),
    ),
    ExecutionErrorCode.timeout => StateError(
      _bashFailureWithCapture(
        error,
        _appendStatus(
          _retryNoticePrefix(notices),
          bashTimeoutStatus(
            timeoutArg: timeoutArg,
            errorMessage: error.message,
          ),
        ),
      ),
    ),
    _ => StateError('${_retryNoticePrefix(notices)}$error'),
  };
}

/// The issue #2201 adoption step of the inline foreground run: hand the
/// exec's survivors to the registry and surface ONE adoption notice in
/// the result notices. No-op without the jobs capability or when the
/// scan found nothing. Split out so [_runForegroundBash] stays under the
/// CRAP ratchet.
Future<void> _adoptExecSurvivors(
  ShellJobRegistry? jobs,
  String command,
  List<ShellSurvivor> survivors,
  List<String> notices,
) async {
  if (jobs == null || !jobs.isSupported || survivors.isEmpty) return;
  final adopted = await jobs.adoptSurvivors(command, survivors, notify: false);
  if (adopted.isNotEmpty) {
    notices.add(adoptedSurvivorsNoticeText(adopted, source: command));
  }
}

/// Appends the killed call's partial capture (stderr after stdout, each
/// tail-truncated to the tool budget) to a bash failure message.
String _bashFailureWithCapture(ExecutionError error, String message) {
  final parts = <String>[
    if (error.stdout.isNotEmpty)
      '--- partial stdout ---\n${_truncateBashOutput(error.stdout)}',
    if (error.stderr.isNotEmpty)
      '--- partial stderr ---\n${_truncateBashOutput(error.stderr)}',
  ];
  return parts.isEmpty ? message : '$message\n${parts.join('\n')}';
}

/// Joins exec stdout and stderr (stderr after stdout).
String _bashOutput(ShellExecResult execResult) {
  final parts = <String>[
    if (execResult.stdout.isNotEmpty) execResult.stdout,
    if (execResult.stderr.isNotEmpty) execResult.stderr,
  ];
  return parts.join('\n');
}
