+  @override
+  Future<Result<ShellExecResult, ExecutionError>> exec(
+    String command, {
+    ShellExecOptions? options,
+  }) async {
+    execCalls++;
+    if (pressuredCalls > 0) {
+      pressuredCalls--;
+      return Err(_fdPressure());
+    }
+    return const Ok(ShellExecResult(stdout: 'ran', stderr: '', exitCode: 0));
+  }
